import type { ShippingRates } from "./types.js";
export function regionBase(region: string, rates: ShippingRates): number {
  const exact = Object.hasOwn(rates.baseByRegion, region) ? rates.baseByRegion[region] : undefined;
  const fallback = Object.hasOwn(rates.baseByRegion, "*") ? rates.baseByRegion["*"] : undefined;
  return exact ?? fallback ?? 0;
}

